package com.darkfleet.common.model;

import java.time.Instant;
import java.util.Map;

/**
 * Candidate anomaly event generated by Track & Detection.
 * Always phrased neutrally (e.g., "unexplained gap" or "potential encounter").
 */
public record DetectionEvent(
        String eventId,
        DetectionType detectionType,
        String neutralTitle,
        String summary,
        String mmsi,
        String secondaryMmsi,
        String vesselName,
        String imoNumber,
        Integer shipType,
        double latitude,
        double longitude,
        String h3Cell,
        CorridorRegion corridor,
        Instant startTime,
        Instant endTime,
        long durationMinutes,
        ConfidenceLevel confidenceLevel,
        double confidenceScore,
        double cellCoverageScore,
        boolean crossSourceChecked,
        boolean seenBySecondaryFeed,
        Double draughtDeltaMeters,
        boolean historical,
        Map<String, Object> evidence
) {
}
